/* Real source-based discovery charts and a browser-local reading history. */
(() => {
 let activeTab='popular';let history=safeRead('nyoh-reading-history',[]);if(!Array.isArray(history))history=[];
 const originalDiscover=window.Nyoh.renderDiscover,originalSongReady=window.Nyoh.songReady;
 const number=value=>new Intl.NumberFormat('en',{notation:value>9999?'compact':'standard',maximumFractionDigits:1}).format(value);
 function ranked(tab){const measured=state.songs.filter(s=>Number.isFinite(s.source_views));if(tab==='popular')return measured.sort((a,b)=>b.source_views-a.source_views).slice(0,6);if(tab==='trending'){const cutoff=Date.now()-90*86400000;return measured.filter(s=>Date.parse(s.source_added_at)>=cutoff).sort((a,b)=>b.source_views-a.source_views).slice(0,6)}if(tab==='new')return state.songs.filter(s=>s.source_added_at).sort((a,b)=>Date.parse(b.source_added_at)-Date.parse(a.source_added_at)).slice(0,6);if(tab==='easy')return state.songs.filter(s=>s.beginner_friendly).slice(0,6);return history.map(item=>({...state.songs.find(s=>s.id===item.id),resume:item.progress||0})).filter(s=>s.id).slice(0,6)}
 const description={popular:'MusiBurma မူရင်းဆိုဒ်၏ စုစုပေါင်းကြည့်ရှုမှုအရ စီထားပါသည်။ NYOH ၏ ကြည့်ရှုမှု မဟုတ်ပါ။',trending:'ပြီးခဲ့သည့် ရက် ၉၀ အတွင်း မူရင်းဆိုဒ်မှာတင်ထားသော သီချင်းများကို စုစုပေါင်းကြည့်ရှုမှုအရ ရွေးထားပါသည်။',new:'မူရင်းဆိုဒ်မှာ တင်ထားသည့်နေ့အလိုက် အသစ်ဆုံးသီချင်းများ။',recent:'ဒီ browser မှာ မကြာသေးခင် ဖွင့်ခဲ့တဲ့သီချင်းတွေ။ ဖတ်လက်စနေရာကနေ ပြန်ဆက်နိုင်ပါတယ်။',easy:'Chord ၅ ခုအထိသာပါပြီး open chords နဲ့ တီးလို့ရတဲ့ သီချင်းများ။'};
 function renderHub(){let hub=$('#discovery-hub');if(!hub){hub=document.createElement('section');hub.id='discovery-hub';$('#collections').after(hub)}hub.hidden=state.view!=='discover'||!!state.query;const list=ranked(activeTab);const sourceCount=state.songs.filter(s=>Number.isFinite(s.source_views)).length;hub.innerHTML=`<div class="section-heading"><div><span class="eyebrow">FIND A SONG WORTH STAYING FOR</span><h2>ဒီတစ်ခါ ဘာတီးကြမလဲ။</h2></div><span class="discovery-count">${number(sourceCount)} ပုဒ်၏ မူရင်းအချက်အလက်</span></div><div class="discovery-tabs" role="group" aria-label="Discover songs">${[['popular','လူကြည့်အများဆုံး'],['trending','Trending picks'],['new','အသစ်ထည့်ထားသော'],['easy','စတင်တီးခတ်သူများ'],['recent','ပြန်ဆက်ဖတ်မယ်']].map(([id,label])=>`<button data-discovery-tab="${id}" class="${activeTab===id?'selected':''}" aria-pressed="${activeTab===id}">${label}</button>`).join('')}</div><p class="chart-description">${description[activeTab]}</p><div class="discovery-chart">${list.map((s,i)=>{const historyItem=history.find(h=>h.id===s.id);const detail=activeTab==='recent'?(historyItem?.progress>.02?`${Math.round(historyItem.progress*100)}% ဖတ်ပြီး · ဆက်ဖတ်မယ်`:'မကြာသေးခင် ဖွင့်ထားသော'):activeTab==='easy'?`${s.chord_count} chords · Open chords`:activeTab==='new'?new Date(s.source_added_at).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):`${number(s.source_views)} ကြည့်ရှုမှု`;return `<button class="chart-song" ${activeTab==='recent'?'data-resume-song':'data-song'}="${s.id}"><span class="chart-rank">${String(i+1).padStart(2,'0')}</span>${window.Nyoh.cover(s)}<span class="chart-song-info"><b>${escapeHtml(s.title)}</b><span>${escapeHtml(s.artist)}</span><small>${detail}</small></span><span class="chart-open">${window.NyohIcon(activeTab==='recent'?'play':'external')}</span></button>`}).join('')||`<div class="chart-empty">${activeTab==='recent'?'သီချင်းတစ်ပုဒ် ဖွင့်ပြီး ကိုယ်ပိုင် reading history လေး စလိုက်ပါ။':'ဒီအမျိုးအစားအတွက် အချက်အလက် မရှိသေးပါ။ “လူကြည့်အများဆုံး” မှာ သီချင်းတွေ ရွေးနိုင်ပါတယ်။'}</div>`}</div><div class="discovery-foot"><span>${activeTab==='trending'?'Trending picks သည် မကြာသေးခင်တင်ထားသော လူကြည့်များသီချင်းများဖြစ်ပြီး live viral chart မဟုတ်ပါ။':activeTab==='popular'?'မူရင်းကြည့်ရှုမှုအရေအတွက်ကို နောက်ဆုံးရယူထားသည့်အချိန်အထိသာ ဖော်ပြထားပါသည်။':''}</span><button class="text-button" data-browse-chart="${activeTab}">စာရင်းအပြည့် ကြည့်မယ် ↗</button></div>`;
 hub.querySelectorAll('[data-discovery-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.discoveryTab;renderHub()});
 }
 function recordSong(s){const previous=history.find(h=>h.id===s.id);history=[{id:s.id,visitedAt:Date.now(),progress:previous?.progress||0},...history.filter(h=>h.id!==s.id)].slice(0,24);persist('nyoh-reading-history',history)}
 function saveProgress(){if(!state.current||!$('#sheet'))return;const sheet=$('#sheet'),top=sheet.getBoundingClientRect().top+window.scrollY;const span=Math.max(1,sheet.offsetHeight-window.innerHeight*.5);const progress=Math.max(0,Math.min(1,(window.scrollY-top)/span));const item=history.find(h=>h.id===state.current.id);if(item&&progress>0){item.progress=progress;persist('nyoh-reading-history',history)}}
 function resume(id){const progress=history.find(h=>h.id===id)?.progress||0;return openSong(id).then(()=>{if(state.current?.id!==id||!$('#sheet'))return;const sheet=$('#sheet');const top=sheet.getBoundingClientRect().top+window.scrollY;window.scrollTo({top:Math.max(0,top+progress*Math.max(1,sheet.offsetHeight-window.innerHeight*.5)-110),behavior:'smooth'})})}
 window.Nyoh.renderDiscover=()=>{originalDiscover();renderHub()};
 window.Nyoh.songReady=s=>{originalSongReady(s);const previous=history.find(h=>h.id===s.id);recordSong(s);if(previous?.progress>.02){$('.reader-tools').insertAdjacentHTML('beforebegin',`<div class="resume-banner"><span>ပြီးခဲ့တဲ့တစ်ခါ ${Math.round(previous.progress*100)}% အထိ ဖတ်ထားပါတယ်။</span><button id="resume-reading">ဖတ်လက်စနေရာသို့ ↗</button></div>`);$('#resume-reading').onclick=()=>resume(s.id)}};
 let scrollTimeout;window.addEventListener('scroll',()=>{clearTimeout(scrollTimeout);scrollTimeout=setTimeout(saveProgress,350)},{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)saveProgress()});
 document.addEventListener('click',e=>{const resumeButton=e.target.closest('[data-resume-song]');if(resumeButton){resume(resumeButton.dataset.resumeSong);return}const browse=e.target.closest('[data-browse-chart]');if(browse){const tab=browse.dataset.browseChart;setView('songs');$('#sort').value=tab==='new'?'source_added_at':tab==='popular'||tab==='trending'?'source_views':'default';if(tab==='easy'){state.query='';state.easyOnly=true}else state.easyOnly=false;state.discoveryMode=tab==='trending'||tab==='recent'?tab:'';state.recentIds=history.map(h=>h.id);$('#list-title').textContent={popular:'မူရင်းလူကြည့်အများဆုံး',trending:'လတ်တလော လူကြည့်များ',recent:'မကြာသေးခင်ဖွင့်ထားသော',new:'အသစ်ဆုံးသီချင်းများ',easy:'စတင်တီးခတ်သူများအတွက်'}[tab];renderList();$('#library').scrollIntoView({behavior:'smooth'})}});
 document.addEventListener('click',e=>{if(e.target.closest('[data-view]'))state.easyOnly=false});
 window.NyohDiscovery={ranked,renderHub};if(state.songs.length)window.Nyoh.renderDiscover();
})();
